  1727	    int32_t x1, int32_t y1, int32_t x2, int32_t y2)
  1728	{
  1729	    lv_area_t area;
  1730	    lv_area_t coords;
  1731	
  1732	    if (!view || !view->canvas || x1 > x2 || y1 > y2) {
  1733	        return;
  1734	    }
  1735	
  1736	    if (x2 < 0 || y2 < 0 || x1 >= view->w || y1 >= view->h) {
  1737	        return;
  1738	    }
  1739	
  1740	    if (view->heading_up) {
  1741	        /* 帧外增量（轨迹尾/导航进度/路线重绘）只改了 C；R 是 C 的快照，
  1742	         * 不作废也不重烘就永远停在旧内容。这里先记账，再按**与角度重烘共用**的
  1743	         * 最小间隔补一次：既保证增量能上屏，又不会因为"每加一个轨迹点"就多烘一次。
  1744	         * 窗口内没补成的由 200 ms 航向拍（vmap_rot_service）兜底，不会永远不补。
  1745	         * 帧在飞时 `vmap_rot_full` 自己会拒绝（pump_phase != 0），帧末会兜底。
  1746	         * 语义上这是"失效"而不是改调用者可见状态 ⇒ 保留 const 形参，只在这一处
  1747	         * 去掉 const（重烘要更新 r_pan/last_bake_ms 这些内部缓存）。 */
  1748	        vmap_view_t * v = (vmap_view_t *)view;
  1749	
  1750	        v->rot_pending = true;
  1751	        vmap_rot_service(v);
  1752	        return;
  1753	    }
  1754	
  1755	    if (x1 < 0) {
  1756	        x1 = 0;
  1757	    }
  1758	    if (y1 < 0) {
  1759	        y1 = 0;
  1760	    }
  1761	    if (x2 >= view->w) {
  1762	        x2 = view->w - 1;
  1763	    }
  1764	    if (y2 >= view->h) {
  1765	        y2 = view->h - 1;
  1766	    }
  1767	
  1768	    lv_obj_get_coords(view->canvas, &coords);
  1769	    area.x1 = coords.x1 + x1;
  1770	    area.y1 = coords.y1 + y1;
  1771	    area.x2 = coords.x1 + x2;
  1772	    area.y2 = coords.y1 + y2;
  1773	    lv_obj_invalidate_area(view->canvas, &area);
  1774	}
  1775	
"}
